    let d = textureLoad(tDepth, q, 0);
    let sceneZ = -viewZFromDepth(ndc, d);
    let rayZ = -pv.z;
    let dz = rayZ - sceneZ;
    let thick = 0.06 + rayZ * 0.004;
    if (dz > 0.004 && dz < thick) { shadow = 1.0 - t * 0.6; break; }
